with valid as (select id, customer_id, device, browser, started_at, country, initcap(trim(device)) device_title, coalesce(country, 'OTHER') country_clean from sessions where started_at > timestamp '2023-04-05 02:00:00'), scored as (select *, last_value(browser, true) over (partition by year(started_at), browser order by started_at, id rows between unbounded preceding and current row) last_known_browser, row_number() over (partition by customer_id order by started_at desc, id) event_seq, last_value(browser, true) over (partition by to_date(started_at), customer_id order by started_at, id rows between unbounded preceding and current row) last_known_browser_2 from valid where customer_id in (17, 24)), metrics as (select id, customer_id, browser, started_at, country, device_title, country_clean, event_seq, min(event_seq) over w_recent running_min_event_seq, max(event_seq) over w_recent running_max_event_seq, count(event_seq) over w_recent running_count_event_seq, avg(event_seq) over w_recent running_avg_event_seq, ntile(5) over w_hist event_seq_bucket from scored window w_recent as (partition by customer_id, browser order by started_at, id rows between unbounded preceding and current row), w_hist as (partition by device, browser order by event_seq, id)), latest as (select *, row_number() over (partition by country, browser order by started_at desc nulls first, id) as dedup_rank from metrics qualify dedup_rank = 1), enriched as (select id, customer_id, started_at, country, device_title, country_clean, running_max_event_seq, running_count_event_seq, running_avg_event_seq, dedup_rank, row_number() over (order by event_seq, id) seq_no, first_value(running_min_event_seq, true) over (partition by customer_id order by running_avg_event_seq, id rows between unbounded preceding and current row) first_known_running_min_event_seq, cume_dist() over (partition by customer_id order by running_count_event_seq nulls first) running_count_event_seq_cume_dist from latest) select * from (select customer_id, country, running_count_event_seq_cume_dist from enriched) src pivot (avg(running_count_event_seq_cume_dist) as total for country in ('JP' as jp, 'US' as us, 'TH' as th))
